import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'auth_provider.dart';

class ProfileScreen extends ConsumerWidget { const ProfileScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref){ final a=ref.watch(authProvider); if(a.loading) return const Scaffold(backgroundColor: Colors.black, body: Center(child: CircularProgressIndicator(color:Color(0xFF1DB954)))); if(a.user==null) return Scaffold(backgroundColor: Colors.black, body: Center(child: Column(mainAxisSize:MainAxisSize.min, children:[const Text('Belum login', style:TextStyle(color:Colors.white)), const SizedBox(height:12), ElevatedButton(style: ElevatedButton.styleFrom(backgroundColor: const Color(0xFF1DB954), foregroundColor: Colors.black), onPressed:()=>context.go('/login'), child: const Text('Login'))]))); return Scaffold(backgroundColor: Colors.black, appBar: AppBar(backgroundColor: Colors.black, title: const Text('Profile')), body: Padding(padding: const EdgeInsets.all(24), child: Column(crossAxisAlignment:CrossAxisAlignment.start, children:[CircleAvatar(radius:36, backgroundColor: const Color(0xFF1DB954), child: Text((a.profile?['display_name']??a.user!.email??'U')[0].toUpperCase(), style: const TextStyle(color:Colors.black, fontSize:24, fontWeight:FontWeight.w800))), const SizedBox(height:12), Text(a.profile?['display_name']??a.user!.email??'', style: const TextStyle(color:Colors.white, fontSize:18, fontWeight:FontWeight.w700)), Text(a.user!.email??'', style: const TextStyle(color:Colors.grey)), const SizedBox(height:24), SizedBox(width:double.infinity, child: OutlinedButton(style: OutlinedButton.styleFrom(foregroundColor: Colors.white, side: const BorderSide(color:Colors.white24)), onPressed:() async { await ref.read(authProvider.notifier).signOut(); if(context.mounted) context.go('/');}, child: const Text('Logout')))])));}}
